#include <RadioLib.h>
// SX1276 on the RFM95W: NSS, DIO0, NRST, DIO1 (pins are examples, set them to your wiring)
SX1276 radio = new Module(5, 26, 14, 33);
void setup() {
  Serial.begin(115200);
  int st = radio.begin(920.2);   // MHz, AS923-2 channel; the chip wakes at 434 MHz
  if (st != RADIOLIB_ERR_NONE) { Serial.println(st); while (true); }
  radio.setSpreadingFactor(7);
  radio.setBandwidth(125.0);
}
void loop() {
  radio.transmit("hello");       // blocks until TxDone
  delay(10000);
}
